package credential
import("context";"crypto/ed25519";"crypto/rand";"errors";"testing";"time";domaincredential "github.com/joshiarheinier/tokenized-credential-verifier/internal/domain/credential";"github.com/joshiarheinier/tokenized-credential-verifier/pkg/connector/blockchain")
const testType="TestPass"
var fixedNow=time.Unix(1_793_000_000,0)
var testSchemas=func()*domaincredential.Schemas{s,e:=domaincredential.NewSchemas(domaincredential.Schema{Type:testType,Fields:[]domaincredential.Field{{Name:"tier",Kind:domaincredential.String,Required:true},{Name:"vip",Kind:domaincredential.Bool,Required:true},{Name:"seats",Kind:domaincredential.Number}}});if e!=nil{panic(e)};return s}()
func newKey(t *testing.T)ed25519.PrivateKey{t.Helper();_,k,e:=ed25519.GenerateKey(rand.Reader);if e!=nil{t.Fatal(e)};return k}
func newSigner(t *testing.T)*domaincredential.Signer{t.Helper();s,e:=domaincredential.NewSigner("did:example:issuer",newKey(t));if e!=nil{t.Fatal(e)};return s}
func verifierTrusting(s *domaincredential.Signer,now time.Time)*domaincredential.Verifier{v:=domaincredential.NewVerifier(testSchemas,func()time.Time{return now});v.Trust(s.IssuerID(),s.PublicKey());return v}
type fakeApprovals struct{approval domaincredential.Approval;err error;calls int}
func(f *fakeApprovals)ConsumeApproval(context.Context,string)(domaincredential.Approval,error){f.calls++;return f.approval,f.err}
type registerCall struct{issuerID,ref [32]byte;exp time.Time}
type fakeBlockchainClient struct{err error;calls []registerCall}
func(f *fakeBlockchainClient)RegisterCredential(_ context.Context,issuerID,ref [32]byte,exp time.Time)(blockchain.WriteResult,error){f.calls=append(f.calls,registerCall{issuerID,ref,exp});return blockchain.WriteResult{},f.err}
func TestServiceIssueFromApproval(t *testing.T){s:=newSigner(t);src:=&fakeApprovals{approval:domaincredential.Approval{Subject:"user-1",CredentialType:testType,Claims:map[string]any{"tier":"gold","vip":false}}};svc,e:=NewService(s,src,testSchemas,24*time.Hour,func()time.Time{return fixedNow});if e!=nil{t.Fatal(e)};issued,e:=svc.IssueFromApproval(context.Background(),"approval-1");if e!=nil{t.Fatal(e)};if want:=fixedNow.Add(24*time.Hour).UTC();!issued.ExpiresAt.Equal(want){t.Errorf("ExpiresAt=%v want %v",issued.ExpiresAt,want)};c,e:=verifierTrusting(s,fixedNow).Verify(issued.Token);if e!=nil{t.Fatalf("issued credential does not verify: %v",e)};if c.Subject!="user-1"||c.CredentialType!=testType||c.Attributes["tier"]!="gold"||c.Attributes["vip"]!=false||c.ID==""{t.Errorf("claims=%+v",c)};second,_:=svc.IssueFromApproval(context.Background(),"approval-1");c2,_:=verifierTrusting(s,fixedNow).Verify(second.Token);if c.ID==c2.ID{t.Error("credential ids are not unique")}}
func TestServicePropagatesApprovalErrors(t *testing.T){sentinel:=errors.New("not approved");svc,_:=NewService(newSigner(t),&fakeApprovals{err:sentinel},testSchemas,time.Hour,nil);if _,e:=svc.IssueFromApproval(context.Background(),"x");!errors.Is(e,sentinel){t.Fatalf("err=%v want %v",e,sentinel)}}
func TestNewServiceValidation(t *testing.T){s:=newSigner(t);if _,e:=NewService(nil,&fakeApprovals{},testSchemas,time.Hour,nil);e==nil{t.Error("nil signer accepted")};if _,e:=NewService(s,nil,testSchemas,time.Hour,nil);e==nil{t.Error("nil approvals accepted")};if _,e:=NewService(s,&fakeApprovals{},nil,time.Hour,nil);e==nil{t.Error("nil schemas accepted")};if _,e:=NewService(s,&fakeApprovals{},testSchemas,0,nil);e==nil{t.Error("zero ttl accepted")}}
func TestServiceRegistersCredentialBeforeReturningIt(t *testing.T){s:=newSigner(t);reg:=&fakeBlockchainClient{};src:=&fakeApprovals{approval:domaincredential.Approval{Subject:"user-1",CredentialType:testType,Claims:map[string]any{"tier":"gold","vip":true}}};svc,_:=NewService(s,src,testSchemas,time.Hour,func()time.Time{return fixedNow},WithBlockchainClient(reg));issued,e:=svc.IssueFromApproval(context.Background(),"approval-1");if e!=nil{t.Fatal(e)};c,e:=verifierTrusting(s,fixedNow).Verify(issued.Token);if e!=nil{t.Fatal(e)};if len(reg.calls)!=1{t.Fatalf("blockchain calls=%d want 1",len(reg.calls))};got:=reg.calls[0];if got.issuerID!=blockchain.IssuerID(s.IssuerID())||got.ref!=blockchain.CredentialRef(c.ID)||!got.exp.Equal(time.Unix(c.ExpiresAt,0)){t.Errorf("registered %+v, want ids and expiry of issued credential",got)}}
func TestServiceReturnsNoCredentialWhenRegistrationFails(t *testing.T){boom:=errors.New("chain down");src:=&fakeApprovals{approval:domaincredential.Approval{Subject:"user-1",CredentialType:testType,Claims:map[string]any{"tier":"gold","vip":true}}};svc,_:=NewService(newSigner(t),src,testSchemas,time.Hour,nil,WithBlockchainClient(&fakeBlockchainClient{err:boom}));issued,e:=svc.IssueFromApproval(context.Background(),"approval-1");if !errors.Is(e,boom)||issued.Token!=""{t.Fatalf("issued=%+v err=%v, want no credential and blockchain error",issued,e)}}
func TestServiceDoesNotRegisterForInvalidApprovals(t *testing.T){reg:=&fakeBlockchainClient{};svc,_:=NewService(newSigner(t),&fakeApprovals{err:errors.New("not approved")},testSchemas,time.Hour,nil,WithBlockchainClient(reg));if _,e:=svc.IssueFromApproval(context.Background(),"x");e==nil{t.Fatal("want error")};if len(reg.calls)!=0{t.Fatal("invalid approval triggered on-chain registration")}}
func TestServiceRejectsApprovalsThatDoNotMatchTheirType(t *testing.T){reg:=&fakeBlockchainClient{};for name,a:=range map[string]domaincredential.Approval{"unknown type":{Subject:"u",CredentialType:"Nope",Claims:map[string]any{"tier":"gold","vip":true}},"claims mismatch":{Subject:"u",CredentialType:testType,Claims:map[string]any{"tier":"gold"}},"unexpected claim":{Subject:"u",CredentialType:testType,Claims:map[string]any{"tier":"gold","vip":true,"ssn":"x"}}}{svc,_:=NewService(newSigner(t),&fakeApprovals{approval:a},testSchemas,3600e9,nil,WithBlockchainClient(reg));issued,e:=svc.IssueFromApproval(context.Background(),"id");if e==nil||issued.Token!=""{t.Errorf("%s: issued=%+v err=%v, want refusal",name,issued,e)}};if len(reg.calls)!=0{t.Fatal("invalid approval must not be registered on chain")}}
